BIZ, NEXT = "2026-10-25", "2026-10-26"
FAM = {"VARCHAR2":"S","CHAR":"S","NCHAR":"S","NVARCHAR2":"S","CLOB":"S",
       "NUMBER":"N","FLOAT":"N","BINARY_FLOAT":"N","BINARY_DOUBLE":"N",
       "DATE":"D","TIMESTAMP":"D","TIMESTAMP(6)":"D","TIMESTAMP(3)":"D"}

oracledb.init_oracle_client(lib_dir="/opt/oracle")
line = open("/etc/data-asset/credentials/ods_8_216").readline().strip()
u, _, p = line.partition(":")
conn = oracledb.connect(user=u, password=p, dsn="10.10.8.216:1521/orcl", tcp_connect_timeout=20)
cur = conn.cursor()
print("table|view|datetime|lob_cols|gap|mismatch(N->S,S->N,S<->D)|wincount")
for tname in sorted(TARGETS):
    view = "V_" + tname
    cur.execute("SELECT COUNT(*) FROM ALL_OBJECTS WHERE OWNER='ODS' AND OBJECT_NAME=:v AND OBJECT_TYPE='VIEW'", {"v": view})
    isview = cur.fetchone()[0] == 1
    cur.execute("SELECT COLUMN_NAME, DATA_TYPE FROM ALL_TAB_COLUMNS WHERE OWNER='ODS' AND TABLE_NAME=:v", {"v": view})
    src = {r[0].upper(): r[1].upper() for r in cur.fetchall()}
    lobs = sorted(c for c, ty in src.items() if ty in ("CLOB","BLOB","NCLOB","LONG"))
    tgt = {c: ty[0].upper() for c, ty in TARGETS[tname].items() if c != "SYSTEM_TIME"}
    gap = sorted(set(tgt) - set(src))
    mism = []
    for c, tty in tgt.items():
        sty = src.get(c)
        if sty is None: continue
        sf, tf = FAM.get(sty,"?"), FAM.get(tty,"?")
        if sf != tf:
            mism.append(f"{c}:{sty[:4]}>{tty[:4]}")
    conn.call_timeout = 60000
    try:
        cur.execute(f"SELECT COUNT(*) FROM ODS.{view} WHERE DATETIME >= TO_DATE(:s,'YYYY-MM-DD') AND DATETIME < TO_DATE(:e,'YYYY-MM-DD')", {"s": BIZ, "e": NEXT})
        wc = cur.fetchone()[0]
    except Exception as exc:
        conn.rollback(); wc = f"ERR({type(exc).__name__}:{str(exc)[:40]})"
    conn.call_timeout = 0
    print(f"{tname}|{isview}|{src.get('DATETIME','-')}|{','.join(lobs) if lobs else '-'}|{','.join(gap) if gap else 'NONE'}|{';'.join(mism) if mism else 'NONE'}|{wc}")
conn.close()
print("== census done ==")
